  // or an older app); "preview": a plain browser can't see your screen, so it shows a demo film.
  const desk = window.lumaDesktop || null;
  // The app's real browser (see "real browser" below), the chat dock and Watch: set up first, used everywhere.
  const native = { on: Boolean(desk?.webCookies), view: null, mode: desk?.webCookies ? "you" : "luma", url: "", title: "", shareTimer: null, follow: true };
  const dock = { open: false };
  const watchState = { built: false };
  const seeHow = !desk ? "preview" : desk.setGlass && desk.platform !== "win32" ? "pixels" : "fade";
  const cleanGlass = (g) => g && (g.mode === "glass" || g.mode === "clear") && typeof g.clarity === "number" && g.clarity >= 0 && g.clarity <= 90 && typeof g.onTop === "boolean"
    ? { mode: g.mode, clarity: Math.round(g.clarity), onTop: g.onTop } : null;
  let glass = { mode: "glass", clarity: 60, onTop: false };
  try { glass = cleanGlass(JSON.parse(localStorage.getItem("luma-glass"))) || glass; } catch (_) { /* private window */ }
  const keepGlass = () => { try { localStorage.setItem("luma-glass", JSON.stringify(glass)); } catch (_) { /* private */ } };
  function applyGlass() {
    const root = document.documentElement;
    const changed = root.dataset.glass !== glass.mode;
    root.dataset.glass = glass.mode;
    root.dataset.see = seeHow;
    root.style.setProperty("--clarity", String(glass.clarity / 100));
    $("scene-demo").hidden = !(seeHow === "preview" && glass.mode === "clear");
    $("top-glass").setAttribute("aria-pressed", String(glass.mode === "clear"));
    if (changed && root.dataset.scene) applyScene(); // the camera rests while you see through
  }
  // live: only repaint (while the slider moves); otherwise remember it and tell the app's window.
  function setGlass(change, live = false) {
    glass = { ...glass, ...change };
    applyGlass();
    if (live) return;
    keepGlass();
    if (desk?.setGlass) desk.setGlass(glass).catch(() => {});
  }
  applyGlass();
  if (scene === "clear") { setScene("glow"); setGlass({ mode: "clear" }); } // See-through used to be one of the scenes
  if (seeHow === "preview") $("top-glass").title = "See-through: a preview here; in the Luma desktop app what's behind it shows through";
  // The app keeps the window's glass, so it wins over this page's copy (or gets it, the first time).
  const fromApp = (g) => { const next = cleanGlass(g); if (!next) return false; glass = next; applyGlass(); keepGlass(); return true; };
  desk?.getGlass?.().then((g) => { if (!fromApp(g)) setGlass({}); }).catch(() => {});
  desk?.onGlass?.((g) => { if (fromApp(g) && state.view === "settings") renderSettings(); });
  // Luma's engine stopped and the app started it again: say so once, kindly, and carry on.
