  // Make a picture small on this computer before it goes anywhere.
  async function shrinkPhoto(file, side, maxChars) {
    const img = await createImageBitmap(file).catch(() => { throw new Error("That isn't a picture Luma can read."); });
    const square = side <= 256;
    const scale = square ? side / Math.min(img.width, img.height) : Math.min(1, side / Math.max(img.width, img.height));
    const c = document.createElement("canvas");
    c.width = square ? side : Math.round(img.width * scale);
    c.height = square ? side : Math.round(img.height * scale);
    const g = c.getContext("2d");
    if (square) g.drawImage(img, (side - img.width * scale) / 2, (side - img.height * scale) / 2, img.width * scale, img.height * scale);
    else g.drawImage(img, 0, 0, c.width, c.height);
    img.close?.();
    for (const q of [0.86, 0.75, 0.62, 0.5, 0.4]) { const out = c.toDataURL("image/jpeg", q); if (out.length <= maxChars) return out; }
    throw new Error("That photo is too big. Try another one.");
  }
  // Your picture where there is one, your initial where there isn't.
